/**
 * sitemap.xml for nooni.dk — generated by Next.js at build time.
 *
 * Add the product detail pages here once their handles are confirmed in
 * Shopify (likely /produkter/dots, /loops, /emblem, /decks,
 * /tic-tac-take — priority 0.8 each). The dynamic route exists already
 * (src/app/produkter/[handle]/page.tsx); the sitemap entries are how
 * we tell Google to index them.
 *
 * Docs: https://nextjs.org/docs/app/api-reference/file-conventions/metadata/sitemap
 */

import type { MetadataRoute } from "next";

const BASE_URL = "https://nooni.dk";

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date();

  return [
    {
      url: `${BASE_URL}/`,
      lastModified: now,
      changeFrequency: "weekly",
      priority: 1,
    },
    {
      url: `${BASE_URL}/om-os`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.6,
    },
  ];
}
